"## Overview and benchmark results

I propose two optimizated implementations, and maybe a bugfix.

Benchmark results with times per element (full benchmark code is at the bottom):

```none
131.0 +- 0.6 ns  previous
130.2 +- 0.6 ns  current
120.5 +- 0.7 ns  proposal_1
107.6 +- 0.2 ns  proposal_2
 92.1 +- 0.5 ns  extreme

Python: 3.15.0 (tags/v3.15.0:d220409a13b, Oct 10 2026, 06:45:03) [Clang 22.1.8 (Fedora 22.1.8-4.fc44)]
```

`previous`/`current` are the implementations before/after yesterday's optimization from @rhettinger in #1313. `proposal_1` and `proposal_2` are my proposals, and `extreme` is just for curiosity.


## The proposals

The current implementation uses this generator:

```python
    def gen(queue):
        append_false = false_queue.append
        append_true = true_queue.append
        while True:
            while queue:
                yield queue.popleft()
            for value in iterator:
                (append_true if pred(value) else append_false)(value)
                break
            else:
                return
```

My `proposal_1` replaces the outer `while True` and single-value `for` loops with one long-running `for` loop:

```python
    def gen(queue):
        append_false = false_queue.append
        append_true = true_queue.append
        while queue:
            yield queue.popleft()
        for value in iterator:
            (append_true if pred(value) else append_false)(value)
            while queue:
                yield queue.popleft()
```

And `proposal_2` avoids putting the new value into the generator's own queue and instead yields it directly:

```python
    def gen(queue):
        while queue:
            yield queue.popleft()
        for value in iterator:
            destination = true_queue if pred(value) else false_queue
            if destination is queue:
                yield value
                while queue:
                    yield queue.popleft()
            else:
                destination.append(value)
```


## The bug

`proposal_2` also happens to fix a current bug, although the bug is obscure, so I don't put much weight on this. Consider the following:

```python
iterable = [1, 2]

def pred(value):
    if value == 1:
        next(falses, None)
    return True

falses, trues = partition(pred, iterable)
print(list(trues))
```

The output is `[2, 1]`, changing the order of the two true values. The reason: The trues-generator fetches a value with `for value in iterator`, then calls `pred(value)`, and then appends `value` to its queue. But the `pred` function sneaks the second value into that queue first, by using the falses-generator. The `proposal_2` implementation avoids this by not putting `value` through the queue at all.


## Benchmark

The benchmark uses this iterable of 20,000 values:

```python
iterable = [True, False] * 10**4
random.shuffle(iterable)
```

It then measures how long it takes to create and consume the partitions like this:

```python
falses, trues = partition(None, iterable)
deque(zip(falses, trues), maxlen=0)
```

<details><summary>Full benchmark script</summary>

```python
def partition_previous(pred, iterable):
    if pred is None:
        pred = bool
    iterator = iter(iterable)

    false_queue = deque()
    true_queue = deque()

    def gen(queue):
        while True:
            while queue:
                yield queue.popleft()
            for value in iterator:
                (true_queue if pred(value) else false_queue).append(value)
                break
            else:
                return

    return gen(false_queue), gen(true_queue)


def partition_current(pred, iterable):
    if pred is None:
        pred = bool
    iterator = iter(iterable)

    false_queue = deque()
    true_queue = deque()

    def gen(queue):
        append_false = false_queue.append
        append_true = true_queue.append
        while True:
            while queue:
                yield queue.popleft()
            for value in iterator:
                (append_true if pred(value) else append_false)(value)
                break
            else:
                return

    return gen(false_queue), gen(true_queue)


def partition_proposal_1(pred, iterable):
    if pred is None:
        pred = bool
    iterator = iter(iterable)

    false_queue = deque()
    true_queue = deque()

    def gen(queue):
        append_false = false_queue.append
        append_true = true_queue.append
        while queue:
            yield queue.popleft()
        for value in iterator:
            (append_true if pred(value) else append_false)(value)
            while queue:
                yield queue.popleft()

    return gen(false_queue), gen(true_queue)


def partition_proposal_2(pred, iterable):
    if pred is None:
        pred = bool
    iterator = iter(iterable)

    false_queue = deque()
    true_queue = deque()

    def gen(queue):
        while queue:
            yield queue.popleft()
        for value in iterator:
            destination = true_queue if pred(value) else false_queue
            if destination is queue:
                yield value
                while queue:
                    yield queue.popleft()
            else:
                destination.append(value)

    return gen(false_queue), gen(true_queue)


def partition_extreme(pred, iterable):
    if pred is None:
        pred = bool
    iterator = iter(iterable)

    false_queue = deque()
    true_queue = deque()

    def falses():
        pop_false = false_queue.popleft
        append_true = true_queue.append
        while false_queue:
            yield pop_false()
        for value in iterator:
            if pred(value):
                append_true(value)
            else:
                yield value
                while false_queue:
                    yield pop_false()

    def trues():
        pop_true = true_queue.popleft
        append_false = false_queue.append
        while true_queue:
            yield pop_true()
        for value in iterator:
            if pred(value):
                yield value
                while true_queue:
                    yield pop_true()
            else:
                append_false(value)

    return falses(), trues()


funcs = [
    partition_previous,
    partition_current,
    partition_proposal_1,
    partition_proposal_2,
    partition_extreme,
]


from collections import deque
import timeit
import random
from statistics import mean, stdev
import sys


# Correctness
iterable = [[] for _ in range(100)] + [[1] for _ in range(100)]
random.shuffle(iterable)
fetches = [True, False] * 100
random.shuffle(fetches)
expect = None
for f in funcs:
    falses, trues = f(None, iterable)
    F, T = [], []
    for fetch in fetches:
        if fetch:
            T.append(id(next(trues)))
        else:
            F.append(id(next(falses)))
    tails = list(falses), list(trues)
    result = F, T, tails
    if expect is None:
        expect = result
        print(len(F), len(T), tails)
    else:
        print(result == expect, f.__name__)

# Bug demo
for f in funcs:
    def pred(value):
        if value == 1:
            next(falses, None)
        return True
    falses, trues = f(pred, [1, 2])
    print(list(trues), f.__name__)


# Speed
iterable = [True, False] * 10**4
random.shuffle(iterable)

def run():
    deque(zip(*f(None, iterable)), maxlen=0)

times = {f: [] for f in funcs}
for _ in range(100):
    for f in random.sample(funcs, len(funcs)):
        t = timeit.timeit(run, number=1) / len(iterable)
        times[f].append(t)
for f in funcs:
    ts = [t * 1e9 for t in sorted(times[f])[:5]]
    print(f'{mean(ts):5.1f} +- {stdev(ts):3.1f} ns ', f.__name__.removeprefix('partition_'))

print('\nPython:', sys.version)
```

